'use strict';
const D=window.LAB_DATA;
const STORAGE='english-lab-v1';
const $=(s,root=document)=>root.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHTML;
const defaults=()=>({answers:{},plan:{},drafts:{},checks:{},listening:{},scores:{},session:null,timer:null,exams:{}});
let state=defaults(),storageOK=true;
try{const raw=JSON.parse(localStorage.getItem(STORAGE)||'null');if(raw&&raw.version===1&&raw.data&&typeof raw.data==='object'){state={...defaults(),...raw.data};for(const k of ['answers','plan','drafts','checks','listening','scores','exams'])if(!state[k]||typeof state[k]!=='object'||Array.isArray(state[k]))state[k]={};if(state.session&&(!Array.isArray(state.session.ids)||!Number.isInteger(state.session.index)||state.session.index<0||state.session.ids.some(id=>!D.questions.some(q=>q.id===id))))state.session=null;}}catch{storageOK=false;}
function save(){try{localStorage.setItem(STORAGE,JSON.stringify({version:1,data:state}));return true;}catch{storageOK=false;notify('Der Browser kann gerade nicht speichern. Exportiere deine Texte und deinen Fortschritt.');return false;}}
let toastId;
function notify(message){const n=$('#notice');n.textContent=message;n.classList.add('show');clearTimeout(toastId);toastId=setTimeout(()=>n.classList.remove('show'),5000);}
const topic=id=>D.grammar.find(t=>t.id===id);
const year=y=>D.years.find(t=>t.year===Number(y))||D.years[0];
const asset=(file,page)=>`material/${encodeURIComponent(file)}${page?'#page='+page:''}`;
const pdfLink=(file,label,page)=>file?`<a href="${asset(file,page)}" target="_blank" rel="noopener">${E(label)} ↗</a>`:'';
const button=(label,action,kind='primary',extra='')=>`<button type="button" class="${kind}" data-action="${action}" ${extra}>${label}</button>`;
const head=(title,sub,kicker='')=>`${kicker?`<p class="section-label">${kicker}</p>`:''}<h1>${title}</h1><p class="intro">${sub}</p>`;
const EXERCISE_NAMES={input:'Selbst schreiben',choice:'Auswählen',order:'Satzpuzzle',error:'Fehler finden'};
function exerciseState(q){const s=state.session;s.exerciseUI??={};const u=s.exerciseUI[q.id]??={value:'',picked:[]};if(!Array.isArray(u.picked))u.picked=[];if(!u.bank&&q.type==='order')u.bank=shuffled(q.parts.map((_,i)=>i));if(!u.options&&q.type==='choice')u.options=shuffled(q.options.map((_,i)=>i));return u;}
function exerciseInput(q,r){const s=state.session,u=exerciseState(q);
 if(q.type==='choice')return `<fieldset class="answer-choices"><legend>Welche Antwort passt?</legend>${u.options.map(i=>`<label class="choice" for="option-${i}"><input id="option-${i}" name="exercise-choice" type="radio" data-exercise-option="${i}" value="${E(q.options[i])}" ${(r?r.answer:u.value)===q.options[i]?'checked':''} ${r?'disabled':''}><span lang="en">${E(q.options[i])}</span></label>`).join('')}</fieldset>`;
 if(q.type==='error')return `<div class="error-parts" role="group" aria-label="Fehlerstelle auswählen">${q.parts.map((part,i)=>`<button class="word-chip" type="button" data-action="error-pick:${i}" aria-pressed="${(r?r.answer:u.value)===part}" ${r?'disabled':''} lang="en">${E(part)}</button>`).join('')}</div><p class="meta small-gap" aria-live="polite">${u.value?'Ausgewählt: '+E(u.value):'Tippe auf den fehlerhaften Baustein und prüfe deine Auswahl.'}</p>`;
 if(q.type==='order')return `<div class="puzzle-answer" role="group" aria-label="Dein zusammengesetzter Satz">${u.picked.length?u.picked.map((i,pos)=>`<button type="button" class="word-chip placed" data-action="puzzle-remove:${pos}" ${r?'disabled':''} aria-label="${E(q.parts[i])} zurücklegen" lang="en">${E(q.parts[i])}</button>`).join(''):'<span class="meta">Hier entsteht dein Satz …</span>'}</div><p class="meta puzzle-count" aria-live="polite">${u.picked.length} von ${q.parts.length} Bausteinen eingesetzt</p><div class="puzzle-bank" role="group" aria-label="Verfügbare Satzbausteine">${u.bank.map(i=>`<button type="button" class="word-chip" data-action="puzzle-add:${i}" ${r||u.picked.includes(i)?'disabled':''} lang="en">${E(q.parts[i])}</button>`).join('')}</div>${button('Satz neu legen','puzzle-clear','text',r?'disabled':'')}`;
 return `<div class="field answer-input"><label for="answer">Deine Antwort</label><input type="text" id="answer" name="answer" autocomplete="off" autocapitalize="off" spellcheck="false" ${r?'readonly':''} value="${E(r?.answer||(s.inputDraftIndex===s.index?s.inputDraft:'')||'')}" aria-describedby="answer-hint"></div><p id="answer-hint" class="meta small-gap">Trage die gesuchte Form oder Wortgruppe ein.</p>`;
}
function practiceAnswer(){const s=state.session,q=D.questions.find(q=>q.id===s.ids[s.index]);if(q.type==='input'||!q.type)return $('#answer')?.value||'';const u=exerciseState(q);return q.type==='order'?u.picked.map(i=>q.parts[i]).join(' '):u.value;}
function exerciseAction(action,value){const s=state.session,q=s&&D.questions.find(q=>q.id===s.ids[s.index]);if(!q||s.responses[q.id])return;const u=exerciseState(q),i=Number(value);let focus='';
 if(action==='error-pick'&&q.type==='error'&&Number.isInteger(i)&&q.parts[i]!==undefined){u.value=q.parts[i];focus=`[data-action="error-pick:${i}"]`;}
 else if(action==='puzzle-add'&&q.type==='order'&&Number.isInteger(i)&&q.parts[i]!==undefined&&!u.picked.includes(i)){u.picked.push(i);focus=`[data-action="puzzle-remove:${u.picked.length-1}"]`;}
 else if(action==='puzzle-remove'&&q.type==='order'&&Number.isInteger(i)&&u.picked[i]!==undefined){const part=u.picked.splice(i,1)[0];focus=`[data-action="puzzle-add:${part}"]`;}
 else if(action==='puzzle-clear'&&q.type==='order'){u.picked=[];focus='[data-action^="puzzle-add:"]';}else return;
 save();render(false);$(focus)?.focus({preventScroll:true});
}
function stats(){let attempted=0,correct=0;for(const q of D.questions){const a=state.answers[q.id];if(a){attempted++;if(a.correct)correct++;}}return{attempted,correct};}
function weakTopics(){return D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id&&state.answers[q.id]);return{...t,attempted:qs.length,wrong:qs.filter(q=>!state.answers[q.id].correct).length};}).filter(t=>t.wrong).sort((a,b)=>b.wrong-a.wrong);}
function targetDays(){const now=new Date();const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(now);const p=Object.fromEntries(parts.map(x=>[x.type,x.value]));return Math.round((Date.UTC(2026,8,29)-Date.UTC(+p.year,+p.month-1,+p.day))/86400000);}
const days=targetDays();$('#countdown').textContent=days>0?`Noch ${days} ${days===1?'Tag':'Tage'} · 29.09.`:days===0?'Heute ist dein Testtag':'Weiterüben nach dem Test';
function planEntries(){return D.plan.map((entry,index)=>({entry,index})).filter(({entry})=>!entry[3].startsWith('writing'));}
function completedPlanCount(){return planEntries().filter(({index})=>state.plan[index]).length;}
function home(){const s=stats(),weak=weakTopics(),done=completedPlanCount();return head('Schritt für Schritt zum Test.','Finde heraus, was schon sitzt. Übe deine Lücken und geh mit einem guten Gefühl in den 29. September.','Dein Lernweg · Schwerpunkt 2021–2025')+`
 <section class="hero-work"><div class="start"><span class="pill accent">Dein nächster Schritt</span><h2 style="margin-top:16px">${weak.length?'Hier kannst du sicherer werden.':s.attempted?'Bleib im Training.':'Was kannst du schon?'}</h2><p class="muted">${weak.length?`Bei <strong>${E(weak[0].title)}</strong> sind noch Fragen offen. Schau dir die Regel an und probiere es erneut.`:s.attempted?'Wende die Regeln auf neue Sätze an. Eine gemischte Runde gibt dir zwölf Aufgaben aus verschiedenen Themen.':'Starte mit zwölf neu entwickelten Fragen. Sie prüfen die wichtigen Grammatikthemen, ohne die Antworten der Originaltests vorwegzunehmen.'}</p><div class="actions">${button(weak.length?'Lücken gezielt üben':s.attempted?'Neue Übungsrunde starten':'Lerncheck starten',weak.length?'start:topic:'+weak[0].id:s.attempted?'start:mixed':'start:diagnostic')}<span class="meta">${weak.length?'Mit Erklärungen':s.attempted?'12 Aufgaben · ca. 15 Min.':'12 Aufgaben · ca. 15 Min.'}</span></div>${state.session&&state.session.index<state.session.ids.length?'<p class="small-gap"><a href="#quiz">Angefangene Übung fortsetzen</a></p>':''}</div><aside class="aside-note"><h3>So übst du wirksam</h3><ol><li>Erst selbst lösen.</li><li>Die Erklärung lesen.</li><li>Fehler später noch einmal versuchen.</li></ol><div class="progress-caption"><span>Zuletzt richtig gelöst</span><strong>${s.correct} / ${D.questions.length}</strong></div><progress value="${s.correct}" max="${D.questions.length}">${s.correct}</progress><p class="meta small-gap">${s.attempted?`${s.attempted} verschiedene Aufgaben bearbeitet.`:'Dein Fortschritt beginnt mit der ersten Antwort.'}</p></aside></section>
 <div class="split"><section><div class="row"><h2>Dein Lernplan</h2><span class="pill" id="plan-count">${done} / ${planEntries().length} Einheiten</span></div><p class="meta">Lerne in deinem eigenen Tempo. Beginne mit dem Lerncheck und wähle danach die Themen, die du wiederholen möchtest.</p><div>${planEntries().map(({entry:p,index:i})=>`<div class="plan-row ${state.plan[i]?'done':''}"><input type="checkbox" id="day-${i}" data-plan="${i}" ${state.plan[i]?'checked':''}><label for="day-${i}"><strong>${p[1]}</strong><span class="meta">${p[2]} · ${p[4]} Min.</span></label><a href="${planHref(p[3])}" class="button secondary">Öffnen</a></div>`).join('')}</div></section>
 <aside><div class="panel"><h3>Das erwartet dich im Test</h3><ul class="flat-list"><li><strong>Listening</strong><div class="meta">Nur in den Originaltests · 15 BE</div></li><li><strong>Use of English</strong><div class="meta">Grammatik sicher anwenden · 15 BE</div></li><li><strong>Sprachmittlung</strong><div class="meta">Nur in den Originaltests · 20 BE</div></li></ul><p class="meta small-gap">Aufbau der bereitgestellten Septembertests 2021–2025: 60 Minuten, keine Hilfsmittel. Dein aktueller Test richtet sich nach den Vorgaben deiner Lehrkraft.</p></div><div class="panel tint"><h3>Deine Fehler sind ein Lernplan.</h3><p class="meta">${weak.length?`${weak.length} Themen bieten sich zum Wiederholen an.`:'Sobald du Fragen beantwortest, findest du hier passende Wiederholungen.'}</p>${weak.slice(0,3).map(t=>`<p><a href="#grammar/${t.id}">${t.title}</a><br><span class="meta">${t.wrong} offene ${t.wrong===1?'Aufgabe':'Aufgaben'}</span></p>`).join('')}<a href="#progress">Fortschritt ansehen</a></div></aside></div>`;}
function planHref(p){const [a,b]=p.split(':');if(['topic','year'].includes(a))return '#start/'+a+'/'+b;if(a==='diagnostic'||a==='mistakes'||a==='mixed')return '#start/'+a;return '#'+(a==='exams'?'exam':a)+(b?'/'+b:'');}
function practice(){const fresh=D.questions.filter(q=>!q.year).length;return head('Neue Aufgaben. Sicheres Wissen.','Übe dieselben Grammatikregeln in anderen Situationen. Jede Antwort bekommt eine Erklärung und einen Link zur passenden Regel.')+`
 <section class="panel tint"><h2>${fresh} eigenständige Übungen</h2><p>Neue Sätze zu Schule, Freizeit, Reisen und Alltag. Pro Thema kannst du Grundlagen festigen, Formen anwenden oder dein Wissen auf neue Zusammenhänge übertragen.</p><div class="actions">${button('Gemischte Runde starten','start:mixed')}${button('Lerncheck starten','start:diagnostic','secondary')}</div><p class="meta small-gap">Zwölf Aufgaben pro gemischter Runde. Noch nicht bearbeitete Fragen kommen zuerst; danach offene Fehler und bereits gelöste Fragen.</p></section>
 <section class="format-picker"><h2>Wähle eine Übungsform</h2><div class="format-buttons">${[['input','✎','Selbst schreiben'],['choice','✓','Antworten auswählen'],['order','↔','Sätze zusammensetzen'],['error','⌕','Fehler finden']].map(([id,icon,label])=>button(`<span aria-hidden="true">${icon}</span><span>${label}<small>${D.questions.filter(q=>!q.year&&(q.type||'input')===id).length} Aufgaben</small></span>`,'start:format:'+id,'secondary')).join('')}</div><p class="meta small-gap">Bis zu zwölf Aufgaben aus verschiedenen Themen. In Themenrunden und gemischten Runden wechseln sich die Übungsformen ab.</p></section>
 <h2>Ein Thema gezielt üben</h2><div class="filters"><div class="field"><label for="practice-topic">Dein Thema</label><select id="practice-topic">${D.grammar.map(t=>`<option value="${t.id}">${t.title}</option>`).join('')}</select></div><div class="field"><label for="practice-level">Schwierigkeit</label><select id="practice-level"><option value="new">Alle neuen Übungen</option><option value="basic">Grundlagen festigen</option><option value="apply">Formen anwenden</option><option value="transfer">Wissen übertragen</option></select></div></div><div class="actions">${button('Thema üben','start-selected')}${button('Fehler wiederholen','start:mistakes','secondary')}</div><p class="meta small-gap">Bis zu zwölf Aufgaben pro Themenrunde. „Fehler wiederholen“ enthält deine offenen Fehler aus neuen Übungen und ausdrücklich gewähltem Originaltraining.</p>
 <details style="margin-top:32px"><summary>Originalaufgaben separat trainieren · 2021–2025</summary><p class="muted">Diese 75 Aufgaben stammen aus den Originaltests. Sie sind ausdrücklich kein neuer Übungsstoff. Für eine unverbrauchte Generalprobe übe zunächst mit den neuen Aufgaben oben.</p><div class="actions">${[2025,2024,2023,2022,2021].map(y=>button('Original '+y,'start:year:'+y,'secondary')).join('')}</div><p class="small-gap"><a href="#exams">Zu den vollständig ausfüllbaren Originaltests</a></p></details>
 <h2 style="margin-top:40px">Erst die Regel verstehen?</h2><div class="grammar-index">${D.grammar.map(t=>topicCard(t)).join('')}</div>`;}
function topicCard(t){return `<a class="topic-link" href="#grammar/${t.id}"><h3>${t.title} <span aria-hidden="true">↗</span></h3><p>${t.sub}</p><p class="meta small-gap">In den Tests: ${t.years.join(', ')}</p></a>`;}
function grammar(id){if(!id||!topic(id))return head('Kurz nachschlagen. Besser verstehen.','Vierzehn Kapitel helfen dir, Lücken aus früheren Klassen zu schließen. Die Beispiele zeigen dir die Regel direkt im Satz.')+`<div class="field"><label for="grammar-search">Thema finden</label><input id="grammar-search" type="search" placeholder="Zum Beispiel: Zeiten, if, Passiv, since …"></div><div class="grammar-index" id="grammar-results">${D.grammar.map(topicCard).join('')}</div>`;const t=topic(id);return `<a class="back" href="#grammar">← Alle Grammatikthemen</a><article class="lesson">${head(t.title,t.sub,`Nachschlagen · Testbezug ${t.years.join(', ')}`)}<p class="rule">${t.rule}</p><h2>Die Regel auf einen Blick</h2><ul>${t.forms.map(f=>`<li>${E(f)}</li>`).join('')}</ul><h2>So sieht das im Satz aus</h2>${t.examples.map(ex=>`<div class="example"><p lang="en">${E(ex[0])}</p><p class="muted">${E(ex[1])}</p></div>`).join('')}<div class="warning"><strong>Typische Stolperfalle</strong><p style="margin:8px 0 0">${E(t.trap)}</p></div><div class="actions">${button('Jetzt dazu üben','start:topic:'+id)}${state.session&&state.session.index<state.session.ids.length?'<a href="#quiz">Zur laufenden Übung</a>':''}</div></article>`;}
function practicePriority(q){const a=state.answers[q.id];return !a?0:a.correct?2:1;}
function shuffled(list){const result=[...list];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]];}return result;}
function orderedPractice(list){const pool=shuffled(list),result=[];for(const priority of [0,1,2]){const groups={};for(const q of pool.filter(q=>practicePriority(q)===priority))(groups[q.type||'input']??=[]).push(q);const types=shuffled(Object.keys(groups));while(types.some(t=>groups[t].length))for(const t of types)if(groups[t].length)result.push(groups[t].shift());}return result;}
function questionSet(kind,value,level='new'){
 if(kind==='diagnostic'){const ids=['n-tenses-05','n-conditionals-08','n-reported-07','n-passive-06','n-ing-08','n-participles-04','n-modals-05','n-comparison-09','n-quantifiers-09','n-prepositions-10','n-relatives-08','n-possessive-06'];return ids.map(id=>D.questions.find(q=>q.id===id));}
 if(kind==='mixed'){const candidates=D.grammar.map(t=>orderedPractice(D.questions.filter(q=>!q.year&&q.topic===t.id))[0]).filter(Boolean);return orderedPractice(candidates).slice(0,12);}
 if(kind==='format')return orderedPractice(D.questions.filter(q=>!q.year&&(q.type||'input')===value)).slice(0,12);
 if(kind==='year')return D.questions.filter(q=>q.year===+value);
 if(kind==='topic')return orderedPractice(D.questions.filter(q=>!q.year&&q.topic===value&&(level==='new'||level==='all'||q.level===level))).slice(0,12);
 if(kind==='mistakes')return D.questions.filter(q=>state.answers[q.id]&&!state.answers[q.id].correct);
 return [];
}
function startSession(kind,value,level){const qs=questionSet(kind,value,level);if(!qs.length){notify(kind==='mistakes'?'Noch keine offenen Fehler. Starte zuerst eine Übung.':'Für diese Auswahl gibt es keine Aufgaben.');go('practice');return;}state.session={kind,value,ids:qs.map(q=>q.id),index:0,responses:{},started:new Date().toISOString()};save();go('quiz');}
function normalize(v,caseSensitive=false){let s=String(v).trim().replace(/[‘’`]/g,"'").replace(/\s+/g,' ').replace(/[.!?]$/,'');return caseSensitive?s:s.toLowerCase();}
function matchAnswer(q,value){return q.answers.some(a=>normalize(a,q.caseSensitive)===normalize(value,q.caseSensitive));}
function quiz(){const ses=state.session;if(!ses)return head('Womit möchtest du starten?','Wähle eine Übung, um deine Grammatikkenntnisse zu festigen.')+'<a class="button" href="#practice">Übung auswählen</a>';if(ses.index>=ses.ids.length)return results();const q=D.questions.find(q=>q.id===ses.ids[ses.index]),r=ses.responses[q.id],t=topic(q.topic);const title=ses.kind==='format'?EXERCISE_NAMES[ses.value]:ses.kind==='diagnostic'?'Dein Lerncheck':ses.kind==='mixed'?'Neue gemischte Übungsrunde':ses.kind==='year'?'Originaltraining '+ses.value:ses.kind==='mistakes'?'Deine Fehlerwerkstatt':t.title;return `<a class="back" href="#practice">← Zur Übungsauswahl</a>${head(title,ses.kind==='diagnostic'?'Versuche es zuerst ohne Hilfe. Der Lerncheck ist keine Note.':'Beachte den Arbeitsauftrag. Bei Schreibweisen zählen britische und amerikanische Varianten, soweit angegeben.')}<div class="progress-caption"><span>Aufgabe ${ses.index+1} von ${ses.ids.length}</span><span>${Math.round(ses.index/ses.ids.length*100)} % bearbeitet</span></div><progress value="${ses.index}" max="${ses.ids.length}"></progress><div class="study-grid" style="margin-top:24px"><section class="exercise"><p class="pill exercise-kind">${EXERCISE_NAMES[q.type]||EXERCISE_NAMES.input}</p><p class="meta">${E(q.source)}</p>${q.instruction?`<p class="meta">${E(q.instruction)}</p>`:''}<p class="sentence" lang="${q.type==='order'?'de':'en'}">${E(q.prompt).replace('___','<strong aria-label="Lücke">________</strong>')}</p><form id="answer-form">${exerciseInput(q,r)}<div class="actions">${r?button(ses.index===ses.ids.length-1?'Auswertung ansehen':'Nächste Aufgabe','next'): '<button type="submit" class="primary">Antwort prüfen</button>'+button('Überspringen','skip','secondary')}</div></form>${r?feedback(q,r):'<div id="answer-feedback" aria-live="polite"></div>'}</section><aside><div class="panel tint"><h3>Passende Grammatik</h3><p>${E(t.sub)}</p><a href="#grammar/${t.id}">${E(t.title)} nachschlagen</a><p class="meta small-gap">Deine Übung bleibt erhalten.</p></div><p class="meta">${q.year?'Diese Aufgabe stammt aus einem Originaltest und wurde für das Einzeltraining aufbereitet. Den vollständigen Test findest du unter „Originaltests online“.':'Diese Aufgabe wurde neu entwickelt. Sie übt prüfungsrelevante Regeln mit einem anderen Satz oder Kontext.'}</p></aside></div>`;}
function feedback(q,r){return `<div class="feedback ${r.correct?'correct':''}" id="answer-feedback" role="status"><h3>${r.correct?'Richtig gelöst.':'Hier steckt eine wichtige Regel.'}</h3>${!r.correct?`<p>${q.type==='error'?'Fehlerstelle':'Passende Antwort'}: <strong lang="en">${E(q.answers[0])}</strong></p>`:''}<p>${E(q.explanation)}</p>${q.correctedSentence?`<p lang="en"><strong lang="de">Richtig:</strong> ${E(q.correctedSentence)}</p>`:''}${q.answers.length>1?`<p class="meta">Auch akzeptiert: ${q.answers.slice(1).map(E).join(' · ')}</p>`:''}<a href="#grammar/${q.topic}">Regel nachschlagen</a></div>`;}
function checkAnswer(value){const s=state.session;if(!s||s.index>=s.ids.length)return;const q=D.questions.find(q=>q.id===s.ids[s.index]);if(s.responses[q.id])return;if(!value.trim()){notify('Gib zuerst eine Antwort ein, wähle eine aus oder überspringe die Aufgabe.');$('#answer')?.focus();return;}const correct=matchAnswer(q,value),r={answer:value,correct,at:new Date().toISOString()};s.responses[q.id]=r;const old=state.answers[q.id];state.answers[q.id]={...r,attempts:(old?.attempts||0)+1,firstCorrect:old?.firstCorrect??correct};save();render(false);$('#answer-feedback')?.scrollIntoView({block:'nearest'});$('.actions button[data-action="next"]')?.focus();}
function results(){const s=state.session;const qs=s.ids.map(id=>D.questions.find(q=>q.id===id));const correct=qs.filter(q=>s.responses[q.id]?.correct).length;const missed=qs.filter(q=>!s.responses[q.id]?.correct);const skipped=qs.filter(q=>!s.responses[q.id]).length;const topics=[...new Set(missed.map(q=>q.topic))];return head('Deine nächste Übung steht fest.','Nutze die Auswertung als Orientierung. Ein Fehler zeigt dir, was du als Nächstes lernen kannst.')+`<section class="panel tint"><p class="result-number">${correct} von ${qs.length} richtig</p><p>${skipped?`${skipped} Aufgaben übersprungen. `:''}${correct===qs.length?'Diese Runde sitzt. Probiere eine neue gemischte Runde, um dein Wissen in anderen Situationen anzuwenden.':'Lies die Erklärungen und wiederhole die offenen Themen später noch einmal.'}</p><p class="meta">Ergebnis dieser Runde. Keine offizielle Testnote und keine sichere Vorhersage für die Prüfung.</p></section>${topics.length?`<h2>Diese Themen lohnen sich</h2><div class="grammar-index">${topics.map(id=>topicCard(topic(id))).join('')}</div>`:''}<h2 style="margin-top:32px">Deine Antworten</h2>${qs.map(q=>{const r=s.responses[q.id];return `<details><summary>${r?.correct?'✓ Richtig':r?'↻ Wiederholen':'○ Übersprungen'} · ${E(topic(q.topic).title)}</summary><p lang="${q.type==='order'?'de':'en'}">${E(q.prompt)}</p><p>Deine Antwort: ${E(r?.answer||'keine Antwort')}</p><p>${q.type==='error'?'Fehlerstelle':'Passende Antwort'}: <strong>${E(q.answers[0])}</strong></p><p>${E(q.explanation)}</p>${q.correctedSentence?`<p lang="en"><strong lang="de">Richtig:</strong> ${E(q.correctedSentence)}</p>`:''}</details>`;}).join('')}<div class="actions">${missed.length?button('Offene Aufgaben erneut üben','retry'):''}<a class="button secondary" href="#home">Zum Lernweg</a><a href="#practice">Andere Übung wählen</a></div>`;}
function yearSelect(id,selected,includeOld=false){return `<div class="field year-select"><label for="${id}">Jahrgang</label><select id="${id}">${D.years.filter(y=>includeOld||y.year>=2021).map(y=>`<option value="${y.year}" ${y.year===selected?'selected':''}>${y.year} · ${E(id==='writing-year'?y.writing:y.listening)}</option>`).join('')}</select></div>`;}
function audioBlock(y){return y.audio?`<audio controls preload="none" aria-label="Hörtext Jahrgangsstufentest ${y.year}" src="${asset(y.audio)}">Dein Browser unterstützt Audio nicht.</audio><p class="meta">${pdfLink(y.audio,'Hördatei separat öffnen')} · Im Übungsmodus darfst du pausieren und zurückspringen.</p>`:'<p>Für diesen Jahrgang wurde keine Hördatei bereitgestellt.</p>';}
function listening(){return head('Hörverstehen gehört zur Prüfung.','Die Hörtexte und Aufgaben bearbeitest du ausschließlich in den Originaltests. So hörst du sie bei deiner Generalprobe zum ersten Mal.')+'<a class="button" href="#exams">Zu den Originaltests</a>'; }
function writing(){return head('Grammatik üben. Originaltests bearbeiten.','Die separate Schreib- und Sprachmittlungsübung wurde entfernt. Sprachmittlung bearbeitest du als Teil der vollständigen Originaltests.')+'<div class="actions"><a class="button" href="#practice">Grammatik üben</a><a class="button secondary" href="#exams">Zu den Originaltests</a></div>'; }
function wordCount(t){return(t.trim().match(/\S+/g)||[]).length;}
function exams(id){const y=year(id||2025);return head('Die Generalprobe beginnt hier.','Bearbeite einen vollständigen Originaltest. Nutze erst danach die Lösungen und notiere, was du noch wiederholen möchtest.')+yearSelect('exam-year',y.year)+`<section class="panel"><div class="row"><div><h2>Originaltest ${y.year}</h2><p class="muted">60 Minuten · Listening 15 BE · Use of English 15 BE · Sprachmittlung 20 BE</p></div><span class="pill accent">Schwerpunkt</span></div><div class="material-links">${pdfLink(y.task,'Aufgaben-PDF öffnen')}${pdfLink(y.solution,'Lösungen nach der Bearbeitung öffnen')}</div>${audioBlock(y)}<details><summary>So funktioniert die Generalprobe</summary><ol><li>Öffne oder drucke die Aufgaben. Lege Papier und Stift bereit.</li><li>Starte die 60 Minuten und den vollständigen Hörtrack. Der Track enthält die Wiederholungen bereits.</li><li>Arbeite danach an Grammatik und Sprachmittlung. Die Zeit umfasst den gesamten Test.</li><li>Keine Nachschlagehilfe während der Generalprobe. Beim Üben darfst du dir zusätzliche Zeit nehmen.</li><li>Vergleiche anschließend mit den offiziellen Lösungen.</li></ol></details><div class="timer"><output id="timer-output" aria-label="Verbleibende Übungszeit">${timerLabel()}</output>${button(state.timer?.running?'Timer pausieren':'60-Minuten-Timer starten / fortsetzen','timer-toggle','secondary')}${button('Timer zurücksetzen','timer-reset','text')}</div><p class="meta small-gap">Der Timer ist eine Lernhilfe. Er läuft bei einem Seitenwechsel oder Neuladen weiter und beendet deine Arbeit nicht automatisch. Bei einer Pause hältst du den Hörtrack selbst an.</p><div id="timer-status" role="status"></div></section><section class="panel"><h2>Deine Selbstauswertung</h2><p class="meta">Trage die mit dem offiziellen Schlüssel ermittelten Punkte ein. Für die Sprachmittlung ist Feedback durch die Lehrkraft besonders hilfreich.</p>${[['listening','Hörverstehen',15],['grammar','Use of English',15],['writing','Sprachmittlung (bereits × 2)',20]].map(([k,l,m])=>`<div class="score-row"><label for="score-${k}">${l} · maximal ${m} BE</label><input id="score-${k}" type="number" min="0" max="${m}" step="${k==='grammar'?1:.5}" data-score="${y.year}:${k}" value="${state.scores[y.year+':'+k]??''}"></div>`).join('')}<p id="score-total" role="status">${scoreText(y.year)}</p><p class="meta">Diese selbst eingetragenen Punkte sind keine automatisch geprüfte Bewertung.</p></section><h2>Alle Materialien ab 2021</h2>${D.years.filter(y=>y.year>=2021).map(materialRow).join('')}<details style="margin-top:32px"><summary>Älteres Zusatzmaterial: 2018 und 2019</summary><p class="meta">Freiwillige Ergänzung. Die Vorbereitung oben konzentriert sich auf 2021–2025. Ältere Punktzahlen und Formate können abweichen.</p>${D.years.filter(y=>y.year<2021).map(materialRow).join('')}</details><p class="source-note">Quelle: die bereitgestellten Jahrgangsstufentests Englisch am Gymnasium und zugehörigen Lösungshinweise. Die Datei „Ergebnisse 2024“ enthält eine Ergebnisübersicht, keine persönlichen Lerndaten. Es wurden keine Materialien für 2020 bereitgestellt.</p>`;}
function materialLabel(file){if(file.endsWith('.mp3'))return'Hördatei';if(file.includes('Aufg'))return'Originalaufgaben';if(file.includes('Ergeb'))return'Ergebnisübersicht';if(file.includes('Loes_2'))return'Bewertungsraster Zusatztest';if(file.includes('Loes'))return'Lösungen Septembertest';if(file.includes('Textprod_2'))return'Zusatztest Schreiben';if(file.includes('Textprod'))return'Zusatztest Schreiben mit Raster';return file;}
function materialRow(y){return `<article class="material-row"><div class="material-year">${y.year}</div><div><h3>${E(y.listening)}</h3><p class="meta">Sprachmittlung: ${E(y.writing)}</p>${y.year===2018?'<p class="meta">Nur Aufgaben vorhanden. Hördatei und offizieller Lösungsschlüssel fehlen.</p>':''}<div class="material-links">${y.files.filter(f=>!f.includes('Textprod')&&!f.includes('Loes_2')).map(f=>pdfLink(f,materialLabel(f))).join('')}</div>${y.year>=2021?`<div class="actions"><a class="button secondary" href="#exam/${y.year}">Originaltest online ausfüllen</a><a href="#start/year/${y.year}">Grammatik einzeln üben</a></div>`:''}</div></article>`;}
function scoreText(y){const vals=['listening','grammar','writing'].map(k=>state.scores[y+':'+k]);if(vals.some(v=>v===''||v===undefined))return'Trage alle drei Bereiche ein, um die Summe zu sehen.';const nums=vals.map(Number);if(nums.some((v,i)=>!Number.isFinite(v)||v<0||v>[15,15,20][i]||(i===1?!Number.isInteger(v):v*2%1)))return'Bitte gültige Punktzahlen innerhalb der Grenzen eintragen.';return`Deine Selbsteinschätzung: ${nums.reduce((a,b)=>a+b,0).toLocaleString('de-DE')} von 50 BE.`;}
function progressPage(){const s=stats();return head('Dein Fortschritt gehört dir.','Alle Angaben bleiben in diesem Browser auf diesem Gerät. Beim Löschen der Browserdaten gehen sie verloren. Es gibt keine Übertragung an deine Lehrkraft.')+`<section class="panel"><h2>${s.correct} Aufgaben zuletzt richtig gelöst</h2><p>${s.attempted} von ${D.questions.length} Aufgaben bearbeitet. Wiederholungen zählen nicht mehrfach.</p><progress value="${s.correct}" max="${D.questions.length}"></progress><p class="meta small-gap">Ein richtig wiederholter Fehler erscheint nicht mehr in der Fehlerwerkstatt.</p><div class="actions">${button('Fehler wiederholen','start:mistakes')}${button('Lernstand herunterladen','export-progress','secondary')}</div></section><h2>Deine Themen im Überblick</h2><ul class="flat-list">${D.grammar.map(t=>{const qs=D.questions.filter(q=>q.topic===t.id),a=qs.filter(q=>state.answers[q.id]),c=a.filter(q=>state.answers[q.id].correct);return`<li><div class="row"><div><a href="#grammar/${t.id}">${t.title}</a><div class="meta">${a.length?`${c.length} zuletzt richtig · ${a.length} bearbeitet`:'Noch nicht geübt'}</div></div><a href="#start/topic/${t.id}">Üben</a></div></li>`;}).join('')}</ul><section class="panel" style="margin-top:32px"><h2>Daten auf diesem Gerät</h2><p class="meta">Gespeichert werden Antworten, vollständige Online-Testbögen, angehakte Lerneinheiten, Hörnotizen, Schreibentwürfe, selbst eingetragene Punkte und die Timer. Kein Name erforderlich. An einem gemeinsam genutzten Gerät können andere diese Inhalte sehen.</p><p class="meta">${storageOK?'Lokales Speichern ist verfügbar.':'Lokales Speichern ist derzeit nicht verfügbar. Nutze die Downloads, bevor du die Seite schließt.'}</p><details><summary>Gesamten Lernstand zurücksetzen</summary><p>Damit löschst du auch alle hier gespeicherten Texte und Hörnotizen. Lade sie vorher herunter.</p>${button('Alle lokalen Lerndaten endgültig löschen','reset-progress','secondary')}</details></section>`;}
function timerSeconds(){if(!state.timer)return 3600;return state.timer.running?Math.max(0,Math.ceil((state.timer.deadline-Date.now())/1000)):Math.max(0,state.timer.remaining??3600);}
function timerLabel(){const s=timerSeconds();return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;}
function toggleTimer(){const remaining=timerSeconds();if(state.timer?.running)state.timer={running:false,remaining};else state.timer={running:true,deadline:Date.now()+(remaining||3600)*1000};save();render(false);}
setInterval(()=>{const el=$('#timer-output');if(el)el.textContent=timerLabel();if(state.timer?.running&&timerSeconds()===0){state.timer={running:false,remaining:0};save();notify('Die 60 Minuten sind um. Beende deine Generalprobe und prüfe deine Antworten.');if($('#timer-status'))$('#timer-status').textContent='Die Übungszeit ist abgelaufen.';}},1000);
function go(hash){if(location.hash==='#'+hash)render();else location.hash=hash;}
function render(focus=true){const [route='home',a,b]=location.hash.slice(1).split('/');if(route==='start'){startSession(a,b);return;}const makers={home,practice,grammar,listening,writing,exams:onlineExamLibrary,exam:onlineTest,progress:progressPage,quiz};const maker=makers[route]||home;$('#main').innerHTML=maker(a);document.querySelectorAll('[data-nav]').forEach(n=>{const active=n.dataset.nav===(route==='quiz'?'practice':route==='exam'?'exams':route);if(active)n.setAttribute('aria-current','page');else n.removeAttribute('aria-current');});if(focus){$('#main').focus({preventScroll:true});window.scrollTo(0,0);} }
function download(name,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function writingExport(key){return`English Lab · Schreibübung ${key}\n\nPlanung\n${state.drafts[key+':plan']||''}\n\nText (${wordCount(state.drafts[key+':text']||'')} Wörter)\n${state.drafts[key+':text']||''}`;}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b)return;const [action,a,v]=b.dataset.action.split(':');if(action==='error-pick'||action.startsWith('puzzle-')){exerciseAction(action,a);return;}if(action==='start'){startSession(a,v);return;}if(action==='start-selected'){startSession('topic',$('#practice-topic').value,$('#practice-level').value);return;}if(action==='next'||action==='skip'){state.session.index++;save();render();return;}if(action==='retry'){const s=state.session;const ids=s.ids.filter(id=>!s.responses[id]?.correct);state.session={kind:'mistakes',ids,index:0,responses:{},started:new Date().toISOString()};save();render();return;}if(action==='timer-toggle'){toggleTimer();return;}if(action==='timer-reset'){if(window.confirm('Timer auf 60 Minuten zurücksetzen?')){state.timer=null;save();render(false);}return;}if(action==='export-writing'){download('English-Lab-Schreibtext-'+a+'.txt',writingExport(a));return;}if(action==='copy-writing'){try{await navigator.clipboard.writeText(state.drafts[a+':text']||'');notify('Text kopiert.');}catch{notify('Kopieren ist nicht verfügbar. Nutze „Text herunterladen“.');}return;}if(action==='export-listening'){const items=D.listeningItems[a];const text=items?items.map((it,i)=>`${i+1}. ${it[0]}\n${state.listening[a+':'+i]||'—'}`).join('\n\n'):state.listening[a+':notes']||'';download('English-Lab-Listening-'+a+'.txt',text);return;}if(action==='export-progress'){const s=stats();download('English-Lab-Lernstand.txt',`English Lab · Lernstand vom ${new Date().toLocaleDateString('de-DE')}\n${s.correct} zuletzt richtig, ${s.attempted} bearbeitet.\n\n`+D.questions.filter(q=>state.answers[q.id]).map(q=>`${state.answers[q.id].correct?'Richtig':'Wiederholen'}: ${q.prompt}\nDeine Antwort: ${state.answers[q.id].answer}\nRegel: ${q.explanation}`).join('\n\n')+'\n\nSCHREIBENTWÜRFE\n'+Object.entries(state.drafts).map(([k,v])=>k+'\n'+v).join('\n\n')+'\n\nHÖRNOTIZEN\n'+Object.entries(state.listening).map(([k,v])=>k+': '+v).join('\n')+'\n\nABGEHAKTE LERNEINHEITEN\n'+planEntries().filter(({index})=>state.plan[index]).map(({entry})=>entry[1]).join('\n'));return;}if(action==='reset-progress'&&window.confirm('Alle Antworten, Texte, Notizen und Fortschritte auf diesem Gerät endgültig löschen?')){state=defaults();save();render();notify('Dein lokaler Lernstand wurde gelöscht.');}});
document.addEventListener('submit',event=>{if(event.target.id==='answer-form'){event.preventDefault();const q=D.questions.find(q=>q.id===state.session.ids[state.session.index]);if(q.type==='order'&&exerciseState(q).picked.length!==q.parts.length){notify('Setze zuerst alle Bausteine in den Satz ein.');return;}checkAnswer(practiceAnswer());}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='answer'&&state.session&&!el.readOnly){state.session.inputDraft=el.value;state.session.inputDraftIndex=state.session.index;save();}if(el.dataset.draft){state.drafts[el.dataset.draft]=el.value;const ok=save();if(el.id==='writing-text')$('#word-count').textContent=wordCount(el.value)+' Wörter';$('#save-status').textContent=ok?'Auf diesem Gerät gespeichert.':'Speichern nicht verfügbar. Bitte Text herunterladen.';}if(el.dataset.listen){state.listening[el.dataset.listen]=el.value;save();}if(el.dataset.score){state.scores[el.dataset.score]=el.value;save();$('#score-total').textContent=scoreText(el.dataset.score.split(':')[0]);}if(el.id==='grammar-search'){const val=el.value.toLocaleLowerCase('de');const matches=D.grammar.filter(t=>JSON.stringify(t).toLocaleLowerCase('de').includes(val));$('#grammar-results').innerHTML=matches.length?matches.map(topicCard).join(''):'<p class="empty">Kein Thema gefunden. Versuche „Zeiten“, „if“ oder „Gerund“.</p>';}});
document.addEventListener('change',event=>{const el=event.target;if(el.dataset.exerciseOption!==undefined){const s=state.session,q=D.questions.find(q=>q.id===s.ids[s.index]);if(!s.responses[q.id]&&q.type==='choice'){exerciseState(q).value=q.options[Number(el.dataset.exerciseOption)];save();}return;}if(el.dataset.plan!==undefined){state.plan[el.dataset.plan]=el.checked;save();el.closest('.plan-row').classList.toggle('done',el.checked);if($('#plan-count'))$('#plan-count').textContent=completedPlanCount()+' / '+planEntries().length+' Einheiten';}if(el.dataset.check){state.checks[el.dataset.check]=el.checked;save();}const routes={'listening-year':'listening','writing-year':'writing','exam-year':'exams'};if(routes[el.id])go(routes[el.id]+'/'+el.value);});
// Keep an unsubmitted answer when consulting a rule or navigating away.
window.addEventListener('hashchange',()=>render());
render(false);
// Optional native agent interface; shares the visible practice flow.
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_grammar_practice',title:'Grammatikübung starten',description:'Öffnet eine Grammatikübung zu einem verfügbaren Thema und ersetzt die laufende Übungsrunde. Bereits gespeicherte Ergebnisse bleiben erhalten.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:D.grammar.map(t=>t.id)}},required:['topic'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>k!=='topic')||!topic(input.topic))throw new Error('Unbekanntes Grammatikthema.');startSession('topic',input.topic);render(false);return{topic:input.topic,questions:state.session.ids.length};}})).catch(()=>{});}catch{}}
